INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7317483, 1141492, 141319, '<td valign="top">I love this image. Wonderful how you "saw" this and the mono treatment you gave it. Very creative. F</td>', 'I love this image. Wonderful how you "saw" this and the mono treatment you gave it. Very creative. F', '2015-02-16 00:07:06.000000', NULL, 0),
(7317484, 1141492, 97225, '<td valign="top">Congrats on the HM, Marla. Well seen, and beautifully done. This appealed to me more and more and I bumped it twice, the last time just before rollover.</td>', 'Congrats on the HM, Marla. Well seen, and beautifully done. This appealed to me more and more and I bumped it twice, the last time just before rollover.', '2015-02-16 00:07:29.000000', NULL, 0),
(7317486, 1141509, 97225, '<td valign="top">Gorgeous scenery and fabulous light. Congrats on the blue.</td>', 'Gorgeous scenery and fabulous light. Congrats on the blue.', '2015-02-16 00:08:47.000000', NULL, 0),
(7317487, 1141380, 19825, '<td valign="top">Very nicely done, Jon. Lovely portrait.</td>', 'Very nicely done, Jon. Lovely portrait.', '2015-02-16 00:09:22.000000', NULL, 0),
(7317488, 1141388, 114285, '<td valign="top">The only image in the top five that meets the challenge WD!</td>', 'The only image in the top five that meets the challenge WD!', '2015-02-16 00:09:45.000000', NULL, 0),
